//! The loop that discovers and generates every reachable function.
//!
//! Each function is generated by a task of its own, so functions are generated
//! in parallel, but only a few for every core at once: the reachable
//! functions are only discovered as they are generated, and can be many more
//! than there are cores. A function waiting its turn is just its instance in
//! a queue, rather than a spawned task holding a future.

use std::{
    collections::{BTreeMap, VecDeque},
    num::NonZero,
    thread,
};

use rayc_hash::FxHashSet;
use rayc_mono_ir::MonoFunctionInstance;
use rayc_qbice::TrackedEngine;
use rayc_tokio::join_set::JoinSet;

use crate::function::{FunctionOutput, generate_function};

/// How many functions are generated at once for every core. A job spends
/// part of its time waiting on engine queries, so there are more jobs than
/// cores to keep every core busy.
const JOBS_PER_CORE: usize = 4;

/// The generated functions, ordered by instance.
///
/// The order depends only on which functions were generated, never on the
/// order they were generated in, so the output is the same whichever job
/// finishes first.
pub(crate) type GeneratedFunctions = BTreeMap<MonoFunctionInstance, FunctionOutput>;

/// Generates every function reachable from a set of roots.
///
/// The coordinator alone decides which functions still need generating: it
/// owns the set of functions ever scheduled, and each generated function only
/// reports the functions it refers to.
#[derive(Debug)]
pub(crate) struct Coordinator {
    engine: TrackedEngine,
    /// The most functions generated at once.
    limit: usize,
    /// Every function ever scheduled, generated or not.
    seen: FxHashSet<MonoFunctionInstance>,
    /// Scheduled functions not being generated yet, first in first out.
    pending: VecDeque<MonoFunctionInstance>,
    /// The functions being generated; their number is never above `limit`.
    generating: JoinSet<FunctionOutput>,
    outputs: GeneratedFunctions,
}

impl Coordinator {
    pub(crate) fn new(engine: &TrackedEngine) -> Self {
        let cores = thread::available_parallelism().map_or(1, NonZero::get);
        Self {
            engine: engine.clone(),
            limit: cores * JOBS_PER_CORE,
            seen: FxHashSet::default(),
            pending: VecDeque::new(),
            generating: JoinSet::new(),
            outputs: BTreeMap::new(),
        }
    }

    /// Generates `roots` and every function reachable from them.
    pub(crate) async fn generate(
        mut self,
        roots: impl IntoIterator<Item = impl Into<MonoFunctionInstance>>,
    ) -> GeneratedFunctions {
        // roots are scheduled in a canonical order, so the functions generated
        // first do not depend on how the caller listed them
        let mut roots = roots.into_iter().map(Into::into).collect::<Vec<_>>();
        roots.sort_unstable();
        for root in roots {
            self.schedule(root);
        }

        // the loop ends once nothing is being generated, and so nothing is
        // pending either: each function is scheduled at most once, finitely
        // many are reachable, and every job finishes
        loop {
            // start pending functions while there is room for them
            while self.generating.len() < self.limit
                && let Some(instance) = self.pending.pop_front()
            {
                self.generating.spawn(generate_function(self.engine.clone(), instance));
            }

            // whichever job finishes first; a panic in it is resumed here
            let Some(output) = self.generating.next().await else {
                break;
            };
            for callee in output.callees() {
                self.schedule(callee.clone());
            }
            self.outputs.insert(output.instance().clone(), output);
        }

        self.outputs
    }

    /// Schedules `instance` unless it has been scheduled before.
    fn schedule(&mut self, instance: MonoFunctionInstance) {
        if self.seen.insert(instance.clone()) {
            self.pending.push_back(instance);
        }
    }
}
